package io.github.vykosmolt.pluton.core

import kotlinx.serialization.decodeFromString
import kotlinx.serialization.json.Json

// The Norman Bridge: English texts read through the French words they inherited after 1066. Ported from the web
// app's englishTokens/enLookup and LANG.clue, with the same cognates.json generated by data/fr/build.py.

data class EnglishToken(
    val start: Int,
    val end: Int,
    val text: String,
    val fr: String?,
    val clue: String,
    val base: String,
    val faux: Boolean,
)

private val EN_WORD = Regex("[A-Za-z]+(?:['’][a-z]+)?")
private val EN_FORMS = listOf<(String) -> String>(
    { it },
    { it.replace(Regex("ies$"), "y") },
    { it.replace(Regex("es$"), "") },
    { it.replace(Regex("s$"), "") },
    { it.replace(Regex("ed$"), "") },
    { it.replace(Regex("ed$"), "e") },
    { it.replace(Regex("d$"), "") },
    { it.replace(Regex("ing$"), "") },
    { it.replace(Regex("ing$"), "e") },
    { it.replace(Regex("ily$"), "y") },
    { it.replace(Regex("ly$"), "") },
    { it.replace(Regex("ness$"), "") },
)

/** [French counterpart, clue code, base English form] for an English word, trying common inflections. */
fun enLookup(word: String, cognates: Map<String, List<String>>): Triple<String, String, String>? {
    val w = word.lowercase().replace(Regex("['’]s$"), "")
    for (form in EN_FORMS) {
        val base = form(w)
        if (base.length >= 4) {
            val hit = cognates[base]
            if (hit != null) return Triple(hit.getOrElse(0) { "" }, hit.getOrElse(1) { "" }, base)
        }
    }
    return null
}

/** Every English word with its offsets and, where it came through French, its French counterpart. */
fun englishTokens(text: String, cognates: Map<String, List<String>>): List<EnglishToken> =
    EN_WORD.findAll(text).map { m ->
        val hit = enLookup(m.value, cognates)
        EnglishToken(
            start = m.range.first,
            end = m.range.last + 1,
            text = m.value,
            fr = hit?.first,
            clue = hit?.second.orEmpty(),
            base = hit?.third.orEmpty(),
            faux = hit?.second?.startsWith("faux:") == true,
        )
    }.toList()

private val JSON = Json { ignoreUnknownKeys = true }

fun decodeCognates(json: String): Map<String, List<String>> = JSON.decodeFromString(json)

/** Why an English word looks like its French twin (matches LANG.clue in src/lib/lang.js). */
fun bridgeClue(code: String, fr: String, en: String): String {
    if (code == "circumflex") return "The circumflex in $fr marks an s French later dropped and English kept: $fr → $en."
    if (code == "es") return "Old French words in es- lost the s and gained é-; English kept the old form: $fr → $en."
    val parts = code.split(">")
    if (parts.size >= 2 && parts[1].isNotBlank()) {
        return "French -${parts[0]} often became English -${parts[1]}: $fr → $en."
    }
    return ""
}

/** The gloss shown when a Bridge word is tapped. */
fun bridgeNote(token: EnglishToken): String {
    val fr = token.fr ?: return ""
    if (token.faux) {
        val meaning = token.clue.removePrefix("faux:")
        return "Faux ami: $fr means “$meaning”, not “${token.base}”."
    }
    return bridgeClue(token.clue, fr, token.base).ifBlank { "${token.base} came into English from French: $fr." }
}
